  gate.people.push({"id":98,"x":13,"y":6,"movement":"face_left","rangeX":1,"rangeY":1,"script":"Route22_NorthEntrance_EventScript_JohtoGuard","flag":null,"text":["The Johto region lies to the west.","I'm sorry, but only the Champion of\nthe Pokémon League may go on to Johto."],"sprite":"policeman","width":16,"height":32,"frames":9});
